function q($v): string
{
    if ($v === null) {
        return 'NULL';
    }
    if (is_bool($v)) {
        return $v ? '1' : '0';
    }
    if (is_int($v) || is_float($v)) {
        return (string) $v;
    }
    if (is_array($v)) {
        $v = json_encode($v, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    }
    return "'" . str_replace(["\\", "'", "\n", "\r"], ["\\\\", "\\'", "\\n", "\\r"], (string) $v) . "'";
}

function ins(string $table, array $rows): string
{
    if (!$rows) {
        return '';
    }
    $cols = array_keys($rows[0]);
    $sql = "INSERT INTO `$table` (`" . implode('`,`', $cols) . "`) VALUES\n";
    $vals = [];
    foreach ($rows as $r) {
        $vals[] = '(' . implode(',', array_map('q', array_values($r))) . ')';
    }
    return $sql . implode(",\n", $vals) . ";\n\n";
}

